def call_atom():
    return _call(3)


def _items(value):
    if value in (None, "Nil"):
        return []
    if isinstance(value, list) and value and value[0] in ("Cons", "cons"):
        out, cur = [], value
        while isinstance(cur, list) and len(cur) == 3 and cur[0] in ("Cons", "cons"):
