    _build_seq += 1
    _build_tree = tree
    _construction_history.clear()
    return 0


def _literal(tree):
    if not isinstance(tree, list) or not tree:
        return None
    if tree[0] == "mkKnob":
        return _literal(tree[1])
    if tree[0] != "mkTree" or len(tree) != 3:
        return None
    op = unwrap_atom(tree[1])
